import { create } from 'zustand'
import { persist } from 'zustand/middleware'

export type LeftPanelTab = 'companion' | 'apps' | 'context' | 'inbox'
export type ThemeMode = 'light' | 'dark' | 'system'
export type AccentPreset = 'green' | 'blue' | 'purple' | 'orange' | 'rose'

type ShellState = {
  leftPanelTab: LeftPanelTab
  leftPanelOpen: boolean
  rightDrawerOpen: boolean
  commandPaletteOpen: boolean
  themeMode: ThemeMode
  accentPreset: AccentPreset
  customAccent: string | null
  gradientFrom: string | null
  gradientTo: string | null
  sidebarCollapsed: boolean

  setLeftPanelTab: (tab: LeftPanelTab) => void
  setLeftPanelOpen: (open: boolean) => void
  setRightDrawerOpen: (open: boolean) => void
  setCommandPaletteOpen: (open: boolean) => void
  setThemeMode: (mode: ThemeMode) => void
  setAccentPreset: (preset: AccentPreset) => void
  setCustomAccent: (hex: string | null) => void
  setGradient: (from: string | null, to: string | null) => void
  setSidebarCollapsed: (collapsed: boolean) => void
  toggleCommandPalette: () => void
}

export const useShellStore = create<ShellState>()(
  persist(
    (set) => ({
      leftPanelTab: 'companion',
      leftPanelOpen: true,
      rightDrawerOpen: false,
      commandPaletteOpen: false,
      themeMode: 'system',
      accentPreset: 'green',
      customAccent: null,
      gradientFrom: null,
      gradientTo: null,
      sidebarCollapsed: false,

      setLeftPanelTab: (tab) => set({ leftPanelTab: tab }),
      setLeftPanelOpen: (open) => set({ leftPanelOpen: open }),
      setRightDrawerOpen: (open) => set({ rightDrawerOpen: open }),
      setCommandPaletteOpen: (open) => set({ commandPaletteOpen: open }),
      setThemeMode: (mode) => set({ themeMode: mode }),
      setAccentPreset: (preset) => set({ accentPreset: preset, customAccent: null }),
      setCustomAccent: (hex) => set({ customAccent: hex }),
      setGradient: (from, to) => set({ gradientFrom: from, gradientTo: to }),
      setSidebarCollapsed: (collapsed) => set({ sidebarCollapsed: collapsed }),
      toggleCommandPalette: () => set((s) => ({ commandPaletteOpen: !s.commandPaletteOpen })),
    }),
    {
      name: 'nox-shell',
      partialize: (s) => ({
        themeMode: s.themeMode,
        accentPreset: s.accentPreset,
        customAccent: s.customAccent,
        gradientFrom: s.gradientFrom,
        gradientTo: s.gradientTo,
        leftPanelTab: s.leftPanelTab,
        sidebarCollapsed: s.sidebarCollapsed,
      }),
    },
  ),
)
